1	package credit
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"reflect"
8		"strings"
9		"unicode/utf8"
10	)
11	
12	// duplicateFieldError 表示同一个 JSON 对象内出现了读取功能无法确定归属的
13	// 两个字段：
14	//   - 字段名完全相同（first == second，如两份 "credit"）；
15	//   - 两个字段名只有大小写差异（编码/json 的大小写折叠等同于
16	//     strings.EqualFold），却都被现有读取功能识别为同一条记录字段
17	//     （如 "credit" 与 "Credit" 都填入课程学分，"courses" 与
18	//     "COURSES" 都填入最外层课程列表）。
19	//
20	// field 是两者共同指向的规范字段名（结构体 json 标签原文）；完全同名时
21	// 与 first、second 相同。
22	type duplicateFieldError struct {
23		field  string
24		first  string
25		second string
26	}
27	
28	func (e *duplicateFieldError) Error() string {
29		if e.first == e.second {
30			return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.first)
31		}
32		return fmt.Sprintf(
33			"同一 JSON 对象内字段名 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定",
34			e.first, e.second, e.field)
35	}
36	
37	// nullCourseOpenError 表示某条课程记录显式提供了开放状态字段，却把值写成
38	// JSON 的 null（"open":null，大小写与 Unicode 转义变体同理）。课程编号、
39	// 名称与学分合法也不能放过：标准库把 null 解进非指针 bool 时不报错、字段
40	// 保持零值 false，于是“状态未确定”的记录被悄悄读成“停开”，课程列表显示
41	// 停开、新增修读被误拒，之后任何一次保存还会把未定状态写成明确的 false。
42	// 这属于记录内容损坏，必须拒绝整份文件，而不是跳过该课程继续办理。
43	//
44	// courseID 是该课程对象内 id 字段解码后的编号（字段位置不影响判定，编号
45	// 出现在开放状态之后也能取到；课程确实没有编号时为空串）；key 是开放状态
46	// 字段的原始写法（解码后文字），用于说明是哪一种写法被写成了 null。
47	type nullCourseOpenError struct {
48		courseID string
49		key      string
50	}
51	
52	func (e *nullCourseOpenError) Error() string {
53		id := e.courseID
54		if id == "" {
55			id = "（该课程记录未提供编号）"
56		}
57		return fmt.Sprintf(
58			"课程 %s 的课程开放状态为空：字段 %q 被显式写成 null，开放状态只能是 true（开放）或 false（停开）",
59			id, e.key)
60	}
61	
62	// scanNullCourseOpen 扫描第一份完整 JSON 值的 token 流：只要某个课程对象
63	// （courses 数组元素，含最外层键的大小写变体与数组嵌套）显式给出开放状态
64	// 字段且值是 JSON null，就返回 *nullCourseOpenError。
65	//
66	// 与 scanDuplicateKeys 同一思路：字段识别直接照搬正常解码的口径——
67	//   - 键名以 JSON 解码后的文字按 strings.EqualFold 与课程结构体的 open
68	//     标签比较，open、Open、OPEN 以及解码后等同于这些写法的 \uXXXX 转义
69	//     都指向同一状态字段，字段在课程对象中的位置不影响结果；
70	//   - 只认“键后紧跟的值 token 就是 nil（JSON null）”这一种情形：字符串
71	//     字面量 "null" 是普通文字，课程名称、免修依据里出现它不算状态空值；
72	//     开放状态写成对象/数组等其他类型留给结构体解码按类型错误拒绝。
73	//
74	// 课程对象之外的 null 不由本检查处理：最外层的 null 或空数组继续按既有
75	// 读取规则判读（顶层 null/数组本来就不是合法记录），"courses":null 这类
76	// 空列表照常按没有课程读取。报错推迟到该课程对象完整读完时发出，这样无论
77	// id 字段出现在开放状态之前还是之后，错误都能点名课程编号。
78	func scanNullCourseOpen(r io.Reader) error {
79		type frame struct {
80			isObj bool
81			// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
82			kind objKind
83			// elem 标识数组元素对象的类型（数组帧使用）。
84			elem objKind
85			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
86			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
87			expectKey bool
88			// pendingKey 是当前值所属的键（解码后文字）。
89			pendingKey string
90			// courseID 记录本课程对象已读到的编号，供报错时点名。
91			courseID string
92			// openNullKey 记录开放状态被写成 null 时该字段的原始写法；
93			// 非空表示本课程对象已构成损坏。
94			openNullKey string
95		}
96		var stack []frame
97		depth := 0
98	
99		push := func(d json.Delim) {
100			switch d {
101			case '{':
102				kind := objUnknown
103				if n := len(stack); n == 0 {
104					kind = objFile
105				} else if p := &stack[n-1]; p.isObj {
106					if p.kind == objFile {
107						kind = fileKeyObjectKind(p.pendingKey)
108					}
109				} else {
110					kind = stack[n-1].elem
111				}
112				stack = append(stack, frame{isObj: true, kind: kind, expectKey: true})
113			case '[':
114				elem := objUnknown
115				if n := len(stack); n > 0 {
116					if p := &stack[n-1]; p.isObj {
117						if p.kind == objFile {
118							elem = fileKeyObjectKind(p.pendingKey)
119						}
120					} else {
121						elem = p.elem
122					}
123				}
124				stack = append(stack, frame{isObj: false, elem: elem})
125			}
126		}
127		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
128		valueEnded := func() {
129			if n := len(stack); n > 0 {
130				f := &stack[n-1]
131				if f.isObj && !f.expectKey {
132					f.expectKey = true
133					f.pendingKey = ""
134				}
135			}
136		}
137	
138		dec := json.NewDecoder(r)
139		for {
140			tok, err := dec.Token()
141			if err == io.EOF {
142				return nil
143			}
144			if err != nil {
145				// 语法问题留给随后的结构体解码报告；本检查只负责发现 null 状态。
146				return nil
147			}
148			switch t := tok.(type) {
149			case json.Delim:
150				switch t {
151				case '{', '[':
152					depth++
153					push(t)
154				case '}', ']':
155					depth--
156					cur := stack[len(stack)-1]
157					if t == '}' && cur.kind == objCourse && cur.openNullKey != "" {
158						// 课程对象已完整读完，id 无论先后都已记录在案。
159						return &nullCourseOpenError{courseID: cur.courseID, key: cur.openNullKey}
160					}
161					stack = stack[:len(stack)-1]
162					if depth == 0 {
163						return nil
164					}
165					valueEnded()
166				}
167			case string:
168				n := len(stack)
169				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
170					f := &stack[n-1]
171					f.expectKey = false
172					f.pendingKey = t
173					continue
174				}
175				// 字符串值：在课程对象内顺带记录编号；普通文字 "null" 是字符串
176				// token 而不是 nil，绝不会被当成开放状态空值。
177				if n > 0 && stack[n-1].isObj {
178					f := &stack[n-1]
179					if f.kind == objCourse {
180						if canonical, ok := matchRecordField(objCourse, f.pendingKey); ok && canonical == "id" {
181							f.courseID = t
182						}
183					}
184					valueEnded()
185				}
186				if depth == 0 {
187					return nil
188				}
189			default:
190				// number、bool 等标量值；JSON null 的 token 是无类型 nil。
191				if n := len(stack); n > 0 && stack[n-1].isObj {
192					f := &stack[n-1]
193					if f.kind == objCourse && tok == nil {
194						if canonical, ok := matchRecordField(objCourse, f.pendingKey); ok && canonical == "open" {
195							// 只记第一处；整份文件都会被拒绝，列出哪一门都成立。
196							if f.openNullKey == "" {
197								f.openNullKey = f.pendingKey
198							}
199						}
200					}
201					valueEnded()
202				}
203				if depth == 0 {
204					return nil
205				}
206			}
207		}
208	}
209	
210	// objKind 标识一个 JSON 对象在记录格式中的位置，用于确定该对象有哪些
211	// “能被现有读取功能识别”的字段名。
212	type objKind int
213	
214	const (
215		objUnknown     objKind = iota // 不属于记录格式的对象（交由结构体解码按未知字段/类型拒绝）
216		objFile                       // 记录最外层 fileData
217		objCourse                     // courses 数组元素：课程
218		objStudent                    // students 数组元素：学生
219		objRequirement                // requirements 数组元素：课程要求
220		objEnrollment                 // enrollments 数组元素：修读
221		objWaiver                     // waivers 数组元素：免修
222	)
223	
224	// recordObjectTypes 把每类对象对应到它在记录格式中的结构体类型。各类对象
225	// “能被读取功能识别哪些字段名”只有结构体定义上的 json 标签这一个出处：
226	// 正常读取时 json.Decoder 按这些标签（先精确名、再大小写折叠名）填入字段，
227	// 重复字段扫描也从同一份结构体定义取字段名。调整一项记录的字段（增删、
228	// 改名、换标签）只需改结构体定义，正常读取与重复检查始终对“哪些字段可
229	// 识别、哪些写法指向同一字段”作出一致判断，不需要再同步另一份字段名称
230	// 清单。
231	var recordObjectTypes = map[objKind]reflect.Type{
232		objFile:        reflect.TypeOf(fileData{}),
233		objCourse:      reflect.TypeOf(Course{}),
234		objStudent:     reflect.TypeOf(Student{}),
235		objRequirement: reflect.TypeOf(Requirement{}),
236		objEnrollment:  reflect.TypeOf(Enrollment{}),
237		objWaiver:      reflect.TypeOf(Waiver{}),
238	}
239	
240	// jsonFieldName 按 encoding/json 的规则给出结构体字段被识别的 JSON 名称：
241	// 未导出字段不参与解码；json 标签为 "-" 的字段跳过（返回空串）；没有标签
242	// 时用 Go 字段名本身；omitempty 等选项不影响名称。记录结构体均为扁平字段，
243	// 无嵌入字段提升问题。
244	func jsonFieldName(sf reflect.StructField) string {
245		if sf.PkgPath != "" {
246			return ""
247		}
248		name := sf.Tag.Get("json")
249		if name == "-" {
250			return ""
251		}
252		if comma := strings.IndexByte(name, ','); comma >= 0 {
253			name = name[:comma]
254		}
255		if name == "" {
256			name = sf.Name
257		}
258		return name
259	}
260	
261	// recordFields 是各类对象能被读取功能识别的字段名（结构体 json 标签原文），
262	// 全部直接取自 recordObjectTypes 中的结构体定义，不在别处另列一份。
263	// 同一对象的字段名在大小写不敏感比较下必须两两不同——否则该格式本身就有
264	// 歧义（两个字段折叠到同一名称），在初始化阶段直接指出这类定义错误。
265	var recordFields = buildRecordFields()
266	
267	func buildRecordFields() map[objKind][]string {
268		m := make(map[objKind][]string, len(recordObjectTypes))
269		for kind, t := range recordObjectTypes {
270			names := make([]string, 0, t.NumField())
271			for i := 0; i < t.NumField(); i++ {
272				name := jsonFieldName(t.Field(i))
273				if name == "" {
274					continue
275				}
276				for _, other := range names {
277					if strings.EqualFold(name, other) {
278						panic(fmt.Sprintf(
279							"记录结构体 %s 的字段 %q 与 %q 在大小写折叠后同名，记录格式存在歧义",
280							t.Name(), name, other))
281					}
282				}
283				names = append(names, name)
284			}
285			m[kind] = names
286		}
287		return m
288	}
289	
290	// matchRecordField 报告键名 key 是否会被现有读取功能填入 kind 对象的某个
291	// 记录字段，命中时返回该字段的规范名称（json 标签原文）。
292	//
293	// encoding/json 解进结构体时先按精确名匹配，不中再按大小写折叠名匹配，
294	// 折叠规则等同于 strings.EqualFold（完整 Unicode 简单折叠，而非仅 ASCII：
295	// 例如 U+212A“K”折到 k、U+0130“İ”折到 i）。这里照搬同一判定，字段名又
296	// 直接来自结构体标签，才能保证“两个键名被现有读取功能识别为同一字段”的
297	// 口径与实际解码完全一致——任何大小写或 Unicode 转义组合都无法让一个键
298	// 绕过本扫描却仍被解码器接受。
299	func matchRecordField(kind objKind, key string) (string, bool) {
300		for _, tag := range recordFields[kind] {
301			if strings.EqualFold(key, tag) {
302				return tag, true
303			}
304		}
305		return "", false
306	}
307	
308	// fileKeyObjectKind 给出最外层对象某个键所对应数组元素/嵌套对象的类型。
309	// 记录格式里只有最外层的五个数组承载记录对象。归属同样直接由 fileData 的
310	// 结构体定义推导：键按大小写折叠命中哪个字段，就取该字段（切片取元素、
311	// 指针解引用）的类型再反查对象类型——courses 与 COURSES 解出来都是课程
312	// 列表，其元素必须按课程对象检查，不能借顶层键的大小写写法绕过限制；
313	// version 等非记录对象字段返回 objUnknown。
314	func fileKeyObjectKind(key string) objKind {
315		t := recordObjectTypes[objFile]
316		for i := 0; i < t.NumField(); i++ {
317			sf := t.Field(i)
318			name := jsonFieldName(sf)
319			if name == "" || !strings.EqualFold(name, key) {
320				continue
321			}
322			ft := sf.Type
323			if ft.Kind() == reflect.Slice {
324				ft = ft.Elem()
325			}
326			if ft.Kind() == reflect.Ptr {
327				ft = ft.Elem()
328			}
329			for kind, rt := range recordObjectTypes {
330				if rt == ft {
331					return kind
332				}
333			}
334			return objUnknown
335		}
336		return objUnknown
337	}
338	
339	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
340	// 字段归属唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后
341	// 是否还拼接了多余内容，那里的报错信息需要与本检查区分开）。
342	//
343	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
344	// 后一个静默覆盖，而且结构体字段按大小写折叠匹配 json 标签（规则等同于
345	// strings.EqualFold）——同一门课程同时写 "credit":4 与 "Credit":9 时，
346	// 标准库读不出“曾经写过两个”，学分直接被后一个值顶替，两个键先后颠倒
347	// 结果也随之颠倒。因此在正常结构体解码之前先单独扫描一遍 token 流。
348	//
349	// 规则：
350	//   - 同一个 JSON 对象内字段归属只能确定一次：完全同名的两个键，或两个
351	//     键名在大小写折叠后都指向同一条可识别记录字段（如 credit 与
352	//     Credit、student 与 Student、courses 与 COURSES），发现即返回
353	//     *duplicateFieldError（含规范字段名与两个原始写法）。
354	//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
355	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
356	//     反转义，所以 "credit"、它的 \uXXXX 转义写法与 "Credit" 之间任意
357	//     两两组合都按解码后实际所指的字段判断，不能用转义加大小写的组合
358	//     绕开限制。
359	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
360	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
361	//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
362	//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
363	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
364	func scanDuplicateKeys(r io.Reader) error {
365		type frame struct {
366			isObj bool
367			// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
368			kind objKind
369			// elem 标识数组元素对象的类型（数组帧使用）。
370			elem objKind
371			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
372			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
373			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
374			// 借此区分字符串 token 是键还是普通字符串值。
375			expectKey bool
376			// pendingKey 是当前值所属的键，用于判断嵌套对象/数组的类型。
377			pendingKey string
378			// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
379			rawKeys map[string]struct{}
380			// seen 记录每条可识别记录字段第一次出现时的原始写法，以规范
381			// 字段名为索引；无法识别的键不进此表。
382			seen map[string]string
383		}
384		var stack []frame
385		depth := 0
386	
387		push := func(d json.Delim) {
388			switch d {
389			case '{':
390				kind := objUnknown
391				if n := len(stack); n == 0 {
392					// 第一份值的根对象即记录最外层；根值不是对象时结构体
393					// 解码阶段自会按类型拒绝。
394					kind = objFile
395				} else if p := &stack[n-1]; p.isObj {
396					if p.kind == objFile {
397						kind = fileKeyObjectKind(p.pendingKey)
398					}
399				} else {
400					// 对象在数组里：类型由承载它的数组决定（数组类型又由
401					// 最外层五个字段之一决定）。
402					kind = stack[n-1].elem
403				}
404				stack = append(stack, frame{
405					isObj: true, kind: kind, expectKey: true,
406					rawKeys: map[string]struct{}{},
407					seen:    map[string]string{},
408				})
409			case '[':
410				elem := objUnknown
411				if n := len(stack); n > 0 {
412					if p := &stack[n-1]; p.isObj {
413						if p.kind == objFile {
414							elem = fileKeyObjectKind(p.pendingKey)
415						}
416					} else {
417						// 数组嵌套：内层数组元素类型跟随外层数组。
418						elem = p.elem
419					}
420				}
421				stack = append(stack, frame{isObj: false, elem: elem})
422			}
423		}
424		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
425		valueEnded := func() {
426			if n := len(stack); n > 0 {
427				f := &stack[n-1]
428				if f.isObj && !f.expectKey {
429					f.expectKey = true
430					f.pendingKey = ""
431				}
432			}
433		}
434	
435		dec := json.NewDecoder(r)
436		for {
437			tok, err := dec.Token()
438			if err == io.EOF {
439				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
440				return nil
441			}
442			if err != nil {
443				return err
444			}
445			switch t := tok.(type) {
446			case json.Delim:
447				switch t {
448				case '{', '[':
449					depth++
450					push(t)
451				case '}', ']':
452					depth--
453					stack = stack[:len(stack)-1]
454					if depth == 0 {
455						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
456						return nil
457					}
458					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
459					valueEnded()
460				}
461			case string:
462				n := len(stack)
463				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
464					f := &stack[n-1]
465					// 对象键：Token() 已按解码后的文字返回，\uXXXX 转义
466					// 形式的键名与直接写出的同名键在这里完全不可区分。
467					if _, dup := f.rawKeys[t]; dup {
468						return &duplicateFieldError{field: t, first: t, second: t}
469					}
470					f.rawKeys[t] = struct{}{}
471					// 只有指向同一条可识别记录字段的不同写法才算归属
472					// 冲突；未知键的大小写变体随后由结构体解码按未知字段
473					// 拒绝（如 "foo" 与 "Foo" 不会被当成任何业务字段）。
474					if canonical, known := matchRecordField(f.kind, t); known {
475						if prev, conflict := f.seen[canonical]; conflict {
476							return &duplicateFieldError{
477								field:  canonical,
478								first:  prev,
479								second: t,
480							}
481						}
482						f.seen[canonical] = t
483					}
484					f.expectKey = false
485					f.pendingKey = t
486					continue
487				}
488				valueEnded()
489				if depth == 0 {
490					return nil // 顶层标量值
491				}
492			default:
493				// number、bool、nil 等标量值。
494				valueEnded()
495				if depth == 0 {
496					return nil
497				}
498			}
499		}
500	}
501	
502	// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
503	// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
504	//   - 字符串中直接写入的字节必须是合法 UTF-8；
505	//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
506	//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
507	//
508	// 背景：encoding/json 解码时会把非法 UTF-8 字节与未配对的代理项转义静默
509	// 替换成 U+FFFD（“�”）。替换后的学生编号、课程名称或免修依据绝不能被当成
510	// 正常内容继续查询、核对或登记——两个本来不同的编号可能被替换成同一个
511	// 而被误判重复或误判相同。因此必须在结构体解码之前按原始字节拒绝这样的
512	// 文件，整份判为内容损坏，哪怕问题只在一条已拒绝免修的依据里、或在与本次
513	// 核对无关的课程名称里。
514	//
515	// 合法文字不受影响：中文、直接写入的补充平面字符、完整的高低代理项转义对、
516	// 用转义表达的控制字符都保留原意；用户确实写入的“�”（U+FFFD，直接写出
517	// 或 \uFFFD 转义）也是合法文字，不能仅因解码结果含有它就拒绝文件。
518	//
519	// 与 scanDuplicateKeys 一样只扫描第一份完整值：完整记录之后的多余内容
520	// 本来就会被读取方拒绝，无需在此重复判定。
521	func scanStringUnicode(raw []byte) error {
522		i := 0
523		for i < len(raw) && isJSONSpace(raw[i]) {
524			i++
525		}
526		if i >= len(raw) {
527			return nil // 空输入交由后续结构体解码报错
528		}
529		switch raw[i] {
530		case '"':
531			// 顶层就是一个字符串：扫描它本身即可。
532			_, err := scanJSONString(raw, i)
533			return err
534		case '{', '[':
535		default:
536			return nil // 顶层标量（数字、true、false、null）不含字符串
537		}
538		depth := 0
539		for i < len(raw) {
540			switch raw[i] {
541			case '"':
542				j, err := scanJSONString(raw, i)
543				if err != nil {
544					return err
545				}
546				i = j
547			case '{', '[':
548				depth++
549				i++
550			case '}', ']':
551				depth--
552				i++
553				if depth == 0 {
554					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
555					return nil
556				}
557			default:
558				i++
559			}
560		}
561		return nil // 未闭合的结构由 JSON 解析报错
562	}
563	
564	// scanJSONString 扫描从 raw[start]（必须是 '"'）开始的一个字符串字面量，
565	// 返回结束引号之后的下标。字符串内容无法还原为合法 Unicode 文字时报错；
566	// 未闭合、非法转义形式等语法问题留给 JSON 解析器报告，本函数不为此报错。
567	func scanJSONString(raw []byte, start int) (int, error) {
568		i := start + 1
569		for i < len(raw) {
570			c := raw[i]
571			switch {
572			case c == '"':
573				return i + 1, nil
574			case c == '\\':
575				if i+1 >= len(raw) {
576					return len(raw), nil
577				}
578				if raw[i+1] != 'u' {
579					i += 2 // 其他转义的合法性由 JSON 解析器校验
580					continue
581				}
582				v, ok := hex4(raw, i+2)
583				if !ok {
584					i += 2 // 非法 \u 转义形式由 JSON 解析器报错
585					continue
586				}
587				switch {
588				case isHighSurrogate(v):
589					// 高位代理项必须紧跟一个 \uXXXX 形式的低位代理项转义。
590					if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
591						if v2, ok := hex4(raw, i+8); ok && isLowSurrogate(v2) {
592							i += 12
593							continue
594						}
595					}
596					return 0, fmt.Errorf(
597						`高位代理项转义 \u%04X 后没有紧跟低位代理项转义`, v)
598				case isLowSurrogate(v):
599					return 0, fmt.Errorf(
600						`低位代理项转义 \u%04X 没有对应的高位代理项转义`, v)
601				default:
602					i += 6
603				}
604			case c < utf8.RuneSelf:
605				i++
606			default:
607				// 直接写入的多字节字符必须是合法 UTF-8。注意 U+FFFD 本身
608				// 是合法文字：只有解码失败（size 为 1）才拒绝。
609				r, size := utf8.DecodeRune(raw[i:])
610				if r == utf8.RuneError && size == 1 {
611					return 0, fmt.Errorf(
612						"字符串中直接写入的字节 0x%02X 不是合法 UTF-8", c)
613				}
614				i += size
615			}
616		}
617		return i, nil // 未闭合的字符串由 JSON 解析器报错
618	}
619	
620	func isJSONSpace(c byte) bool {
621		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
622	}
623	
624	func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
625	func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }
626	
627	// hex4 把 b[i:i+4] 读作四位十六进制数。
628	func hex4(b []byte, i int) (rune, bool) {
629		if i+4 > len(b) {
630			return 0, false
631		}
632		var v rune
633		for k := 0; k < 4; k++ {
634			c := b[i+k]
635			var d byte
636			switch {
637			case '0' <= c && c <= '9':
638				d = c - '0'
639			case 'a' <= c && c <= 'f':
640				d = c - 'a' + 10
641			case 'A' <= c && c <= 'F':
642				d = c - 'A' + 10
643			default:
644				return 0, false
645			}
646			v = v*16 + rune(d)
647		}
648		return v, true
649	}
