28	// Load 从 path 读取记录。
29	//
30	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
31	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
32	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
33	// 空文件同样视为损坏，而不是空记录。
34	//
35	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
36	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
37	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
38	// 绝不依据已读到的前半条记录继续办理业务。
39	//
40	// 同一个 JSON 对象内的字段归属只能确定一次：出现两个完全同名的字段，或
41	// 两个字段名只有大小写差异却都会被读取功能识别为同一条记录字段（课程的
42	// credit 与 Credit、修读的 student 与 Student、最外层的 courses 与
43	// COURSES 等），无论两个值是否相同、顺序是否相邻，整份文件都判为损坏。
44	// 规则同时适用于最外层对象与其中的每条课程、学生、要求、修读、免修记录：
45	// 后一份即使是空数组也不能盖掉前一份。字段名以 JSON 解码后的文字比较并
46	// 按现有解码规则做大小写折叠（直接写出、Unicode 转义、大小写写法语义
47	// 等同），无法用转义加大小写的组合绕开；限制只针对同一对象，不同记录
48	// 各自携带同名字段是正常结构，字符串值里提到字段名不算重复。只出现一次
49	// 的大小写写法仍照常识别（如只有 Credit 的课程按该值读取）；不指向任何
50	// 记录字段的未知键不在此列，继续按未知字段拒绝。
51	//
52	// JSON 字符串的原始内容必须能还原为合法 Unicode 文字：字符串中直接写入的
53	// 字节不是合法 UTF-8，或 \uXXXX 转义中出现未配对的高位/低位代理项（高位
54	// 代理项后没有紧跟低位代理项、孤立的低位代理项、两个高位代理项相连等），
55	// 整份文件都判为内容损坏——标准库会把这些内容静默替换成 U+FFFD，替换后的
56	// 编号或依据绝不能当成正常内容继续查询、核对或登记，哪怕问题只在一条已拒绝
57	// 免修的依据里或本次核对不涉及的课程名称里。检查只读不写：不替用户修补转义、
58	// 不删字符、不改动任何申请状态。合法文字不受影响：中文、直接写入的补充平面
59	// 字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实写入的
60	// “�”（U+FFFD）都按原样使用。
61	//
62	// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
63	// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
64	// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
65	// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
66	// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
67	// 含实际文字的依据中原有空白。
68	//
69	// 课程开放状态字段显式写成 JSON null（"open":null，open、Open、OPEN 及解码
70	// 后等同的 Unicode 转义写法都指向同一字段，字段在课程对象中的位置不影响
71	// 结果）时，整份记录按内容损坏拒绝读取。标准库把 null 解进普通 bool 不报错，
72	// 字段保持零值 false，未定状态会被读成明确停开，进而误拒新增修读，并在后续
73	// 保存时把 null 固化成 false；因此只要课程编号、名称、学分合法而开放状态
74	// 显式为空，就拒绝整份文件——该课程尚未被要求引用、本次只查看另一名学生
75	// 也不跳过它继续办理。true（开放）与 false（停开）仍是合法状态，停开课程
76	// 照常可以建立要求、已有修读照常提交成绩；字段完全省略时沿用既有读取规则，
77	// 本次不改动。课程名称、免修依据中的普通文字“null”（字符串值）不是状态空值；
78	// 最外层 null、空数组或空列表继续按各自既有规则读取。检查只读不写：不补填
79	// 状态、不删除课程、不另存部分记录。
80	func Load(path string) (s *Store, existed bool, err error) {
81		f, err := os.Open(path)
82		if err != nil {
83			if errors.Is(err, os.ErrNotExist) {
84				return NewStore(), false, nil
85			}
86			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
87		}
88		defer f.Close()
89	
90		fi, err := f.Stat()
91		if err != nil {
92			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
93		}
94		if fi.Size() == 0 {
95			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
96		}
97	
98		raw, err := io.ReadAll(f)
99		if err != nil {
100			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
101		}
102	
103		// 先按原始字节检查 JSON 字符串能否还原为合法 Unicode 文字。标准库解码
104		// 会把非法 UTF-8 字节与未配对的高/低位代理项转义静默替换成 U+FFFD，
105		// 替换后的学生编号、课程名称或免修依据绝不能当成正常内容继续办理业务
106		// （两个本来不同的编号可能被替换成同一个），这样的文件整份判为内容
107		// 损坏，哪怕问题只在一条已拒绝免修的依据里或本次核对不涉及的课程名称
108		// 里。检查只读不写：不修补转义、不删字符、不改动申请状态。
109		if err := scanStringUnicode(raw); err != nil {
110			return nil, true, fmt.Errorf(
111				"记录文件 %s 内容损坏（包含无效的 Unicode 文字：%v），未做任何修改",
112				path, err)
113		}
114	
115		// 先在 token 流上检查同一 JSON 对象内的字段归属。标准库直接解进结构
116		// 体时会用后一个重复键静默覆盖前一个，而且结构体字段按大小写不敏感
117		// 匹配 json 标签：同一门课程写了 "credit":4 与 "Credit":9（4 会被
118		// 9 悄悄顶替，两个键颠倒又变成 4），最外层同时写 courses 与 COURSES
119		// （后一份即使是空数组也会盖掉前一份），修读里的 student 与 Student
120		// 都无法明确说明字段归属。这样的记录必须整份判为损坏，绝不能据此
121		// 核对或办理——即使冲突只在本次查询没有涉及的课程或免修历史里。
122		// 仅扫描第一份完整值，其后内容仍由下方的“完整记录之后不得有多余
123		// 内容”检查处理。
124		var dupErr *duplicateFieldError
125		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
126			if dupErr.first == dupErr.second {
127				return nil, true, fmt.Errorf(
128					"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
129					path, dupErr.field)
130			}
131			return nil, true, fmt.Errorf(
132				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定），未做任何修改",
133				path, dupErr.first, dupErr.second, dupErr.field)
134		}
135	
136		// 显式的 "open":null 必须在结构体解码之前拦截。标准库把 JSON null 解进
137		// 非指针 bool 时既不报错也不改字段，零值 false 会被原样保留——于是“开放
138		// 状态未确定”的课程被读成“停开”：课程列表显示停开、新增修读被误拒，
139		// 之后任何一次需要保存的操作还会把未定状态写成明确的 false。因此只要
140		// 课程对象显式给出开放状态字段（open/Open/OPEN 及解码后等同的 Unicode
141		// 转义写法，位置不限）而值是 null，整份文件判为内容损坏，哪怕该课程
142		// 尚未被任何要求引用、本次只查看另一名学生也不跳过它继续办理。扫描只读
143		// 不写：不补填状态、不删除课程；字段省略时的既有读取规则（按零值处理）
144		// 不在此列，课程名称、免修依据中的普通文字“null”也不是状态空值。
145		var openNullErr *nullCourseOpenError
146		if err := scanNullCourseOpen(bytes.NewReader(raw)); errors.As(err, &openNullErr) {
147			return nil, true, fmt.Errorf(
148				"记录文件 %s 内容损坏（%v），未做任何修改", path, err)
149		}
150	
151		var data fileData
152		dec := json.NewDecoder(bytes.NewReader(raw))
153		dec.DisallowUnknownFields()
154		if err := dec.Decode(&data); err != nil {
155			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
156		}
157		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
158		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
159		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
160		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
161		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
162		// 片段。这些一律视为文件损坏。
163		var extra json.RawMessage
164		switch err := dec.Decode(&extra); {
165		case errors.Is(err, io.EOF):
166			// 唯一一份完整记录之后只有空白，符合格式。
167		case err == nil:
168			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
169		default:
170			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
171		}
172	
173		s = NewStore()
174		if err := s.loadData(&data); err != nil {
175			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
176		}
177		return s, true, nil
178	}
179	
180	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
181	func (s *Store) loadData(d *fileData) error {
182		if d.Version != recordVersion {
183			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
184		}
185	
186		// 课程
187		for _, c := range d.Courses {
188			if c == nil {
189				return errors.New("存在空的课程记录")
190			}
191			if c.ID == "" {
192				return errors.New("存在没有编号的课程")
193			}
194			if c.Name == "" {
195				return fmt.Errorf("课程 %s 没有名称", c.ID)
196			}
197			if c.Credit <= 0 {
198				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
199			}
200			if _, dup := s.courseByID[c.ID]; dup {
201				return fmt.Errorf("课程编号 %s 重复", c.ID)
202			}
203			s.courses = append(s.courses, c)
204			s.courseByID[c.ID] = c
205		}
206	
207		// 学生
208		for _, st := range d.Students {
209			if st == nil || st.ID == "" {
210				return errors.New("存在没有编号的学生记录")
211			}
212			if _, dup := s.studentByID[st.ID]; dup {
213				return fmt.Errorf("学生编号 %s 重复", st.ID)
214			}
215			s.students = append(s.students, st)
216			s.studentByID[st.ID] = st
217		}
218	
219		// 要求
220		for _, r := range d.Requirements {
221			if r == nil {
222				return errors.New("存在空的课程要求记录")
223			}
224			if r.StudentID == "" || r.ID == "" {
225				return errors.New("存在缺少学生编号或要求编号的课程要求")
226			}
227			if _, ok := s.studentByID[r.StudentID]; !ok {
228				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
229			}
230			if _, ok := s.courseByID[r.CourseID]; !ok {
231				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
232					r.StudentID, r.ID, r.CourseID)
233			}
234			key := reqKey(r.StudentID, r.ID)
235			if _, dup := s.reqByKey[key]; dup {
236				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
237			}
238			dk := dupKey(r.StudentID, r.CourseID)
239			if other, dup := s.reqByDup[dk]; dup {
240				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
241					r.StudentID, r.CourseID, other, r.ID)
242			}
243			s.requirements = append(s.requirements, r)
244			s.reqByKey[key] = r
245			s.reqByDup[dk] = r.ID
246		}
247	
248		// 修读
249		usedSeq := map[int]bool{}
250		for _, e := range d.Enrollments {
251			if e == nil {
252				return errors.New("存在空的修读记录")
253			}
254			if e.StudentID == "" || e.ID == "" {
255				return errors.New("存在缺少学生编号或修读编号的修读记录")
256			}
257			if _, ok := s.studentByID[e.StudentID]; !ok {
258				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
259			}
260			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
261			if r == nil {
262				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
263					e.StudentID, e.ID, e.ReqID)
264			}
265			if e.Term == "" {
266				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
267			}
268			switch e.Result {
269			case Enrolled, Passed, Failed:
270			default:
271				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
272			}
273			if e.Result == Enrolled {
274				if e.ResultSeq != 0 {
275					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
276				}
277			} else {
278				if e.ResultSeq <= 0 {
279					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
280				}
281				if usedSeq[e.ResultSeq] {
282					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
283				}
284				usedSeq[e.ResultSeq] = true
285			}
286			key := reqKey(e.StudentID, e.ID)
287			if _, dup := s.enrByKey[key]; dup {
288				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
289			}
290			s.enrollments = append(s.enrollments, e)
291			s.enrByKey[key] = e
292		}
293	
294		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
295		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
296		approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
297		for _, w := range d.Waivers {
298			if w == nil {
299				return errors.New("存在空的免修记录")
300			}
301			if w.StudentID == "" || w.ID == "" {
302				return errors.New("存在缺少学生编号或免修编号的免修记录")
303			}
304			if _, ok := s.studentByID[w.StudentID]; !ok {
305				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
306			}
307			switch w.Status {
308			case WaiverApproved, WaiverRejected, WaiverRevoked:
309			default:
310				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
311			}
312			switch w.Status {
313			case WaiverApproved:
314				// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
315				// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
316				// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
317				// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
318				// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
319				// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
320				if blankBasis(w.Basis) {
321					return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
322						w.StudentID, w.ID)
323				}
324				rk := reqKey(w.StudentID, w.ReqID)
325				if s.reqByKey[rk] == nil {
326					return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
327				}
328				if other, dup := approvedReq[rk]; dup {
329					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
330						w.StudentID, w.ReqID, other, w.ID)
331				}
332				approvedReq[rk] = w.ID
333			case WaiverRevoked:
334				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
335				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
336				// 该免修所属学生名下（同号要求只在其他学生名下不算），
337				// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
338				// 空格、不换行空格等同样不算实际依据）。检查只读不写，
339				// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
340				// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
341				// 性限制。
342				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
343					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
344						w.StudentID, w.ID, w.ReqID)
345				}
346				if blankBasis(w.Basis) {
347					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
348				}
349			}
350			key := reqKey(w.StudentID, w.ID)
351			if _, dup := s.waiverByKey[key]; dup {
352				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
353			}
354			s.waivers = append(s.waivers, w)
355			s.waiverByKey[key] = w
356		}
357	
358		if d.NextResultSeq < 0 {
359			return errors.New("结果提交序号计数器为负数")
360		}
361		for seq := range usedSeq {
362			if seq > d.NextResultSeq {
363				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
364			}
365		}
366		s.nextResultSeq = d.NextResultSeq
367		return nil
368	}
369	
370	// invalidTextError 表示待保存记录中含有无法原样写入文件的文字：某个字符串
371	// 字段不是合法 UTF-8。category 指出记录类别（课程、学生、课程要求、修读、
372	// 免修），id 是该条记录的编号（仅用于定位，编号本身也可能就是问题所在，
373	// 按原始字节呈现），field 指出具体字段。
374	type invalidTextError struct {
375		category string
376		id       string
377		field    string
378	}
379	
380	func (e *invalidTextError) Error() string {
381		return fmt.Sprintf(
382			"%s记录（编号 %s）的字段“%s”含无法原样保存的非法 UTF-8 文字",
383			e.category, e.id, e.field)
384	}
385	
386	// validateSaveText 检查全部待写入记录的字符串字段是否都是合法 UTF-8。
387	//
388	// 背景：encoding/json 在序列化时会把字符串里的非法 UTF-8 字节静默替换成
389	// U+FFFD（“�”）却照常返回成功。若直接保存，免修依据会被改写，两个本来
390	// 不同的学生编号还可能被替换成同一个编号，让原本可读的记录文件变成编号
391	// 重复的损坏文件，而命令却提示成功。因此凡是要写入文件的文字——课程、
392	// 学生、课程要求、修读、免修的编号、名称、学期、依据、原因等——都必须先
393	// 通过本检查，任何一个字段不合法就拒绝整次保存。
394	//
395	// 检查只读不补：绝不替换、清空或修补任何原始字符串，也不删除出问题的
396	// 那条历史（即使它只是一条已拒绝或已撤销的免修），更不会跳过该字段只存
397	// 其他记录。合法文字不受影响：中文、补充平面字符、用户确实输入的“�”
398	// （U+FFFD）都是合法 UTF-8；编号中合法的控制字符与免修依据中原有的空白
399	// 也原样保留。命令行里字面出现的“\uD800”只是反斜线加普通字母数字，是
400	// 合法 ASCII 文字，不按记录文件中的 Unicode 转义处理。
401	func (s *Store) validateSaveText() error {
402		for _, c := range s.courses {
403			if c == nil {
404				continue
405			}
406			if err := checkSaveText("课程", c.ID, "编号", c.ID); err != nil {
407				return err
408			}
409			if err := checkSaveText("课程", c.ID, "名称", c.Name); err != nil {
410				return err
411			}
412		}
413		for _, st := range s.students {
414			if st == nil {
415				continue
416			}
417			if err := checkSaveText("学生", st.ID, "编号", st.ID); err != nil {
418				return err
419			}
420		}
421		for _, r := range s.requirements {
422			if r == nil {
423				continue
424			}
425			if err := checkSaveText("课程要求", r.ID, "编号", r.ID); err != nil {
426				return err
427			}
428			if err := checkSaveText("课程要求", r.ID, "学生编号", r.StudentID); err != nil {
429				return err
430			}
431			if err := checkSaveText("课程要求", r.ID, "课程编号", r.CourseID); err != nil {
432				return err
433			}
434		}
435		for _, e := range s.enrollments {
436			if e == nil {
437				continue
438			}
439			if err := checkSaveText("修读", e.ID, "编号", e.ID); err != nil {
440				return err
441			}
442			if err := checkSaveText("修读", e.ID, "学生编号", e.StudentID); err != nil {
443				return err
444			}
445			if err := checkSaveText("修读", e.ID, "要求编号", e.ReqID); err != nil {
446				return err
447			}
448			if err := checkSaveText("修读", e.ID, "学期", e.Term); err != nil {
449				return err
450			}
451			if err := checkSaveText("修读", e.ID, "结果", string(e.Result)); err != nil {
452				return err
453			}
454		}
455		for _, w := range s.waivers {
456			if w == nil {
457				continue
458			}
459			if err := checkSaveText("免修", w.ID, "编号", w.ID); err != nil {
460				return err
461			}
462			if err := checkSaveText("免修", w.ID, "学生编号", w.StudentID); err != nil {
463				return err
464			}
465			if err := checkSaveText("免修", w.ID, "要求编号", w.ReqID); err != nil {
466				return err
467			}
468			if err := checkSaveText("免修", w.ID, "依据", w.Basis); err != nil {
469				return err
470			}
471			if err := checkSaveText("免修", w.ID, "状态", string(w.Status)); err != nil {
472				return err
473			}
474			if err := checkSaveText("免修", w.ID, "原因", w.Reason); err != nil {
475				return err
476			}
477		}
478		return nil
479	}
480	
481	// checkSaveText 校验单个待保存字段的文字是否为合法 UTF-8。
482	func checkSaveText(category, id, field, value string) error {
483		if !utf8.ValidString(value) {
484			return &invalidTextError{category: category, id: id, field: field}
485		}
486		return nil
487	}
488	
489	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
490	// 避免写到一半时损坏原文件。
491	//
492	// 写入前先校验全部待保存字符串都是合法 UTF-8：标准库序列化会把非法字节
493	// 静默替换成 U+FFFD，因此含非法文字的数据绝不能进入序列化与临时文件阶段。
494	// 校验失败时整次保存直接返回错误——不创建/不改动目标文件（目标原本不
495	// 存在时也不会留下新记录文件或临时文件），不替换、清空或修补待保存记录
496	// 中的任何原始字符串，即使问题只出现在一条已拒绝或已撤销免修的字段里。
497	func (s *Store) Save(path string) (err error) {
498		if err := s.validateSaveText(); err != nil {
499			return fmt.Errorf("记录中存在无法原样保存的文字，拒绝写入 %s：%w", path, err)
500		}
501		data := fileData{
502			Version:       recordVersion,
503			Courses:       s.courses,
504			Students:      s.students,
505			Requirements:  s.requirements,
506			Enrollments:   s.enrollments,
507			Waivers:       s.waivers,
508			NextResultSeq: s.nextResultSeq,
509		}
510		buf, err := json.MarshalIndent(&data, "", "  ")
511		if err != nil {
512			return fmt.Errorf("无法序列化记录：%w", err)
513		}
514		buf = append(buf, '\n')
515	
516		dir := filepath.Dir(path)
517		if dir == "" {
518			dir = "."
519		}
520		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
521		if err != nil {
522			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
523		}
524		tmpName := tmp.Name()
525		defer func() {
526			if err != nil {
527				tmp.Close()
528				os.Remove(tmpName)
529			}
530		}()
531		if _, err = tmp.Write(buf); err != nil {
532			return fmt.Errorf("写入记录文件失败：%w", err)
533		}
534		if err = tmp.Sync(); err != nil {
535			return fmt.Errorf("写入记录文件失败：%w", err)
536		}
537		if err = tmp.Close(); err != nil {
538			return fmt.Errorf("写入记录文件失败：%w", err)
539		}
540		if err = os.Chmod(tmpName, 0o600); err != nil {
541			return fmt.Errorf("设置记录文件权限失败：%w", err)
542		}
543		if err = os.Rename(tmpName, path); err != nil {
544			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
545		}
546		return nil
547	}
