1	package credit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件回归“课程开放状态字段显式写成 JSON null 属于记录内容损坏”。
12	//
13	// 旧实现把课程开放状态存成普通 bool：标准库把 "open":null 解进 bool 时既不
14	// 报错也不改字段，零值 false 被原样保留——于是“状态尚未确定”的记录被读成
15	// 明确“停开”：课程列表显示停开、新增修读被误拒，之后任何一次需要保存的
16	// 操作还会把 null 固化成 false。修复后这样的文件整份判为损坏：
17	//   - Load 直接返回错误，不返回可继续使用的记录集，文件标记为已存在；
18	//   - 错误点名记录文件与课程编号，并说明课程开放状态为空；
19	//   - open/Open/OPEN 及解码后等同的 Unicode 转义写法都指向同一字段，字段
20	//     在课程对象中的位置不影响结果，编号出现在状态之后也照样点名；
21	//   - 问题课程尚未被要求引用、记录里另有与它无关的学生，也不跳过它继续
22	//     办理；
23	//   - 只读检查，原文件逐字节保留。
24	//
25	// 不在本次纠正范围：字段完全省略时沿用既有读取规则；true/false 是合法
26	// 状态，false（停开）课程仍可建立要求、已有修读仍可提交成绩并参与核对；
27	// 课程名称、免修依据中的普通文字“null”不是状态空值；表示空列表的
28	// "courses":null 等照常按没有记录读取。
29	
30	// JSON 源文本中的 \uXXXX 转义键片段（不含两侧引号，引号由用例拼接），
31	// 写入文件后 JSON 解码分别为 "open"、"OPEN" 与大写 "N"。这里用 Go 原始
32	// 字符串，反斜线逐字保留，正好模拟记录文件中的 Unicode 转义写法。
33	const (
34		escapedOpenKeyLower = `\u006fpen`
35		escapedOpenKeyUpper = `\u004fPEN`
36		escapedUpperN       = `\u004e`
37	)
38	
39	// nullOpenRejectCases 各案的课程编号、名称与学分都合法，只有开放状态被
40	// 显式写成 null。wantKey 是错误信息应点名的字段原始写法（解码后文字）。
41	var nullOpenRejectCases = map[string]struct {
42		content string
43		course  string
44		wantKey string
45	}{
46		"小写open显式null": {
47			`{"version":1,"courses":[` +
48				`{"id":"c1","name":"数学","credit":4,"open":null}]}` + "\n",
49			"c1", "open",
50		},
51		"首字母大写Open": {
52			`{"version":1,"courses":[` +
53				`{"id":"c1","name":"数学","credit":4,"Open":null}]}` + "\n",
54			"c1", "Open",
55		},
56		"全大写OPEN": {
57			`{"version":1,"courses":[` +
58				`{"id":"c1","name":"数学","credit":4,"OPEN":null}]}` + "\n",
59			"c1", "OPEN",
60		},
61		"状态字段在最前位置不影响": {
62			`{"version":1,"courses":[` +
63				`{"open":null,"id":"c1","name":"数学","credit":4}]}` + "\n",
64			"c1", "open",
65		},
66		"编号出现在null之后仍点名课程": {
67			`{"version":1,"courses":[` +
68				`{"name":"数学","credit":4,"open":null,"id":"c1"}]}` + "\n",
69			"c1", "open",
70		},
71		"unicode转义小写键": {
72			`{"version":1,"courses":[` +
73				`{"id":"c1","name":"数学","credit":4,"` + escapedOpenKeyLower + `":null}]}` + "\n",
74			"c1", "open",
75		},
76		"unicode转义大写键": {
77			`{"version":1,"courses":[` +
78				`{"id":"c1","name":"数学","credit":4,"` + escapedOpenKeyUpper + `":null}]}` + "\n",
79			"c1", "OPEN",
80		},
81		"部分转义混合大小写": {
82			`{"version":1,"courses":[` +
83				`{"id":"c1","name":"数学","credit":4,"ope` + escapedUpperN + `":null}]}` + "\n",
84			"c1", "opeN",
85		},
86		"顶层COURSES变体里的null状态": {
87			`{"version":1,"COURSES":[` +
88				`{"id":"c1","name":"数学","credit":4,"open":null}]}` + "\n",
89			"c1", "open",
90		},
91		"问题课程未被任何要求引用": {
92			`{"version":1,"courses":[` +
93				`{"id":"c9","name":"无关课程","credit":1,"open":null}],` +
94				`"students":[{"id":"s1"}]}` + "\n",
95			"c9", "open",
96		},
97		"多门课程中第二门状态为空": {
98			`{"version":1,"courses":[` +
99				`{"id":"c1","name":"数学","credit":4,"open":true},` +
100				`{"id":"c2","name":"物理","credit":3,"Open":null}]}` + "\n",
101			"c2", "Open",
102		},
103		"嵌套数组中的课程状态为空": {
104			`{"version":1,"courses":[[` +
105				`{"id":"c3","name":"化学","credit":2,"open":null}]]}` + "\n",
106			"c3", "open",
107		},
108	}
