110	func TestLoadRejectsNullCourseOpen(t *testing.T) {
111		for name, tc := range nullOpenRejectCases {
112			t.Run(name, func(t *testing.T) {
113				path := filepath.Join(t.TempDir(), "records.json")
114				if err := os.WriteFile(path, []byte(tc.content), 0o600); err != nil {
115					t.Fatal(err)
116				}
117				s, existed, err := Load(path)
118				if err == nil {
119					t.Fatalf("开放状态显式为 null 必须拒绝整份文件，却得到 store=%v", s)
120				}
121				if s != nil {
122					t.Fatalf("拒绝时不得返回可继续使用的记录集，得到 %v", s)
123				}
124				if !existed {
125					t.Fatal("损坏文件应标记为已存在")
126				}
127				msg := err.Error()
128				for _, want := range []string{path, "内容损坏", tc.course, "开放状态为空", "null", tc.wantKey} {
129					if !strings.Contains(msg, want) {
130						t.Fatalf("错误信息应包含 %q，得到：%v", want, err)
131					}
132				}
133				got, readErr := os.ReadFile(path)
134				if readErr != nil {
135					t.Fatal(readErr)
136				}
137				if string(got) != tc.content {
138					t.Fatalf("拒绝读取不得改动原文件\nwant=%q\n got=%q", tc.content, got)
139				}
140			})
141		}
142	}
143	
144	// TestLoadNullOpenCourseRejectedEvenWhenUnrelated 记录结构完整：s1 的要求
145	// 指向另一门开放课程，null 开放状态的 c2 没有任何人引用；即使本次只想核对
146	// s1，Load 也必须整体失败——不能跳过 c2 办理。
147	func TestLoadNullOpenCourseRejectedEvenWhenUnrelated(t *testing.T) {
148		content := `{
149	  "version": 1,
150	  "courses": [
151	    {"id": "c1", "name": "数学", "credit": 4, "open": true},
152	    {"id": "c2", "name": "物理", "credit": 3, "open": null}
153	  ],
154	  "students": [{"id": "s1"}],
155	  "requirements": [{"id": "r1", "student": "s1", "course": "c1"}],
156	  "enrollments": [
157	    {"id": "e1", "student": "s1", "req": "r1", "term": "2024春",
158	     "result": "passed", "resultSeq": 1}
159	  ],
160	  "waivers": [],
161	  "nextResultSeq": 1
162	}
163	`
164		path := filepath.Join(t.TempDir(), "records.json")
165		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
166			t.Fatal(err)
167		}
168		s, existed, err := Load(path)
169		if err == nil {
170			t.Fatalf("未引用的 null 状态课程也必须整份拒绝，却得到 store=%v", s)
171		}
172		if s != nil || !existed {
173			t.Fatalf("应返回 nil 记录集并标记文件已存在，s=%v existed=%v", s, existed)
174		}
175		if msg := err.Error(); !strings.Contains(msg, "c2") || !strings.Contains(msg, "开放状态为空") {
176			t.Fatalf("错误应点名课程 c2 并说明开放状态为空，得到：%v", err)
177		}
178		if got, readErr := os.ReadFile(path); readErr != nil || string(got) != content {
179			t.Fatalf("拒绝读取不得改写原文件，readErr=%v", readErr)
180		}
181	}
