183	// TestScanNullCourseOpen 直接覆盖扫描器边界：只有课程对象内指向开放状态
184	// 字段、且值 token 确为 JSON null 时才报错。
185	func TestScanNullCourseOpen(t *testing.T) {
186		badCases := map[string]string{
187			"小写":           `{"version":1,"courses":[{"id":"c1","open":null}]}`,
188			"字段在最前":        `{"courses":[{"open":null,"id":"c1"}]}`,
189			"大写变体":         `{"courses":[{"id":"c1","OPEN":null}]}`,
190			"转义键":          `{"courses":[{"id":"c1","` + escapedOpenKeyLower + `":null}]}`,
191			"多层嵌套数组":       `{"courses":[[{"id":"c1","open":null}]]}`,
192			"课程在多元素数组末尾":   `{"courses":[{"id":"c1","open":true},{"id":"c2","open":false},{"id":"c3","open":null}]}`,
193			"先null后id仍能定位": `{"courses":[{"open":null,"credit":2,"name":"x","id":"c7"}]}`,
194		}
195		for name, in := range badCases {
196			t.Run("拒绝/"+name, func(t *testing.T) {
197				var e *nullCourseOpenError
198				err := scanNullCourseOpen(strings.NewReader(in))
199				if !errors.As(err, &e) {
200					t.Fatalf("应返回 *nullCourseOpenError（输入 %q），得到 %T: %v", in, err, err)
201				}
202			})
203		}
204	
205		okCases := map[string]string{
206			"open为true":        `{"version":1,"courses":[{"id":"c1","credit":4,"open":true}]}`,
207			"open为false合法停开":   `{"version":1,"courses":[{"id":"c1","credit":4,"open":false}]}`,
208			"省略open":           `{"version":1,"courses":[{"id":"c1","credit":4}]}`,
209			"课程名称是文字null":      `{"courses":[{"id":"c1","name":"null","credit":4,"open":true}]}`,
210			"课程名称含null字样":      `{"courses":[{"id":"c1","name":"null 导论","credit":4}]}`,
211			"免修依据是文字null":      `{"students":[{"id":"s1"}],"waivers":[{"id":"w1","student":"s1","req":"r","basis":"null","status":"rejected"}]}`,
212			"courses是空数组":      `{"version":1,"courses":[]}`,
213			"courses是null空列表":  `{"version":1,"courses":null}`,
214			"各列表均为null":        `{"version":1,"courses":null,"students":null,"requirements":null,"enrollments":null,"waivers":null}`,
215			"最外层null按原规则":      `null`,
216			"最外层空数组按原规则":       `[]`,
217			"课程内未知字段为null":     `{"courses":[{"id":"c1","credit":4,"open":true,"bogus":null}]}`,
218			"嵌套对象内的open不属课程状态": `{"courses":[{"id":"c1","credit":4,"open":true,"extra":{"open":null}}]}`,
219			"open的值是字符串null":   `{"courses":[{"id":"c1","credit":4,"open":"null"}]}`,
220			"open的值是数字":        `{"courses":[{"id":"c1","credit":4,"open":0}]}`,
221			"空输入留给解码阶段":        ``,
222			"语法不完整留给解码阶段":      `{"courses":[{"id":"c1","open":`,
223		}
224		for name, in := range okCases {
225			t.Run("放过/"+name, func(t *testing.T) {
226				if err := scanNullCourseOpen(strings.NewReader(in)); err != nil {
227					t.Fatalf("不应报告开放状态为空（输入 %q），得到 %v", in, err)
228				}
229			})
230		}
231	}
232	
233	// TestLoadOmittedOpenKeepsLegacyReadRule 本次只纠正“显式 null”：字段完全
234	// 省略的课程继续按既有读取规则（零值 false，即停开）读取，不扩大判定。
235	func TestLoadOmittedOpenKeepsLegacyReadRule(t *testing.T) {
236		content := `{"version":1,"courses":[` +
237			`{"id":"c1","name":"数学","credit":4}]}` + "\n"
238		path := filepath.Join(t.TempDir(), "records.json")
239		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
240			t.Fatal(err)
241		}
242		s, existed, err := Load(path)
243		if err != nil || !existed {
244			t.Fatalf("省略 open 字段应按既有规则读取，existed=%v err=%v", existed, err)
245		}
246		c := s.Course("c1")
247		if c == nil || c.Open {
248			t.Fatalf("省略 open 的既有读取结果应是停开（false），得到 %+v", c)
249		}
250	}
251	
252	// TestLoadClosedCourseStillUsable false 是合法停开状态：停开课程仍可建立
253	// 要求，停开前已有的修读仍能提交成绩并参与核对，停开只限制新增修读。
254	func TestLoadClosedCourseStillUsable(t *testing.T) {
255		d := &fileData{
256			Version: recordVersion,
257			Courses: []*Course{
258				{ID: "c1", Name: "数学", Credit: 4, Open: false},
259				{ID: "c2", Name: "物理", Credit: 3, Open: true},
260			},
261			Students: []*Student{{ID: "s1"}, {ID: "s2"}},
262			Requirements: []*Requirement{
263				{ID: "r1", StudentID: "s1", CourseID: "c1"},
264			},
265			Enrollments: []*Enrollment{
266				{ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春", Result: Enrolled},
267			},
268		}
269		path, raw := writeRecord(t, d)
270	
271		s, existed, err := Load(path)
272		if err != nil || !existed {
273			t.Fatalf("显式 false 的停开课程必须正常读取，existed=%v err=%v", existed, err)
274		}
275		if c := s.Course("c1"); c == nil || c.Open {
276			t.Fatalf("c1 应为合法停开课程，得到 %+v", c)
277		}
278	
279		// 停开课程仍可建立要求。
280		if r, a, err := s.AddRequirement("s2", "r2", "c1"); err != nil || a != ActionCreated {
281			t.Fatalf("停开课程应仍可建立要求，得到 %+v action=%v err=%v", r, a, err)
282		}
283		// 停开只限制新增修读。
284		if _, _, err := s.AddEnrollment("s2", "r2", "2024秋", "e2"); err == nil ||
285			!strings.Contains(err.Error(), "已停开") {
286			t.Fatalf("停开课程新增修读应被拒绝，得到 %v", err)
287		}
288		// 停开前已有的修读仍能提交成绩。
289		if e, changed, err := s.SubmitResult("s1", "e1", Passed); err != nil || !changed ||
290			e.Result != Passed {
291			t.Fatalf("停开前的已有修读应能提交通过，得到 %+v changed=%v err=%v", e, changed, err)
292		}
293		// 并参与核对：s1 得到该课程 4 学分。
294		if rep := s.CheckStudent("s1"); !rep.Found || rep.TotalCredits != 4 ||
295			len(rep.Unmet) != 0 {
296			t.Fatalf("停开课程的通过修读应照常计学分，得到 %+v", rep)
297		}
298		// 重新保存后仍可读取且状态仍为停开。
299		path2 := filepath.Join(t.TempDir(), "r2.json")
300		if err := s.Save(path2); err != nil {
301			t.Fatalf("Save: %v", err)
302		}
303		reloaded, _, err := Load(path2)
304		if err != nil {
305			t.Fatalf("合法停开记录保存后应可再次读取：%v", err)
306		}
307		if c := reloaded.Course("c1"); c == nil || c.Open {
308			t.Fatalf("重存后 c1 应仍为停开，得到 %+v", c)
309		}
310		if got, readErr := os.ReadFile(path); readErr != nil || string(got) != string(raw) {
311			t.Fatalf("原文件不应被只读操作改写，readErr=%v", readErr)
312		}
313	}
314	
315	// TestLoadNullTextInStringFieldsUnchanged 课程名称、免修依据里的普通文字
316	// “null”是字符串值，不是开放状态空值，记录照常读取。
317	func TestLoadNullTextInStringFieldsUnchanged(t *testing.T) {
318		d := &fileData{
319			Version: recordVersion,
320			Courses: []*Course{
321				{ID: "c1", Name: "null", Credit: 4, Open: true},
322			},
323			Students: []*Student{{ID: "s1"}},
324			Waivers: []*Waiver{
325				{ID: "w1", StudentID: "s1", ReqID: "rX", Basis: "课程名称里也有 null",
326					Status: WaiverRejected, Reason: "目标要求 rX 不存在或不属于该学生"},
327			},
328		}
329		path, _ := writeRecord(t, d)
330		s, _, err := Load(path)
331		if err != nil {
332			t.Fatalf("字符串值中的普通文字 null 不应触发损坏：%v", err)
333		}
334		if c := s.Course("c1"); c == nil || c.Name != "null" || !c.Open {
335			t.Fatalf("课程名称为文字 null 的课程应原样读取，得到 %+v", c)
336		}
337	}
338	
339	// TestLoadNullAndEmptyListsReadAsNoRecords 最外层各记录列表写成空数组或
340	// null 都表示没有该类记录，继续按原规则读取为空记录。
341	func TestLoadNullAndEmptyListsReadAsNoRecords(t *testing.T) {
342		content := `{"version":1,"courses":null,"students":[],"requirements":null,` +
343			`"enrollments":[],"waivers":null,"nextResultSeq":0}` + "\n"
344		path := filepath.Join(t.TempDir(), "records.json")
345		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
346			t.Fatal(err)
347		}
348		s, existed, err := Load(path)
349		if err != nil || !existed {
350			t.Fatalf("空数组/null 列表应按空记录读取，existed=%v err=%v", existed, err)
351		}
352		if len(s.Courses()) != 0 || len(s.Students()) != 0 {
353			t.Fatalf("应为空记录，得到课程=%d 学生=%d", len(s.Courses()), len(s.Students()))
354		}
355	}
