	if got, readErr := os.ReadFile(path); readErr != nil || string(got) != content {
		t.Fatalf("拒绝读取不得改写原文件，readErr=%v", readErr)
	}
}

// TestScanNullCourseOpen 直接覆盖扫描器边界：只有课程对象内指向开放状态
// 字段、且值 token 确为 JSON null 时才报错。
