219	// TestLoadUnknownFieldCaseVariantsUnchanged 不指向任何记录字段的未知键不
220	// 属于大小写归并限制：单个未知键继续按未知字段拒绝；两个大小写不同的
221	// 未知键也不会被误报成记录字段冲突，最终仍由结构体解码按未知字段拒绝，
222	// 行为与既有未知字段拒绝一致。
223	func TestLoadUnknownFieldCaseVariantsUnchanged(t *testing.T) {
224		cases := map[string]string{
