251	// TestScanDuplicateKeysCaseFolding 直接覆盖扫描器的大小写归并边界。
252	func TestScanDuplicateKeysCaseFolding(t *testing.T) {
253		okCases := map[string]string{
254			"课程只写一次大写Credit": `{"version":1,"courses":[` +
255				`{"id":"c1","name":"数学","Credit":4,"open":true}]}`,
256			"顶层只写一次大写COURSES": `{"VERSION":1,"COURSES":[]}`,
257			"不同可识别字段不冲突": `{"version":1,"courses":[` +
258				`{"id":"c1","name":"数学","credit":4,"open":true}]}`,
