  ],
  "STUDENTS": [{"ID": "s1"}, {"ID": "S1"}],
  "REQUIREMENTS": [
    {"ID": "r1", "STUDENT": "s1", "COURSE": "c1"},
    {"ID": "r1", "Student": "S1", "Course": "c1"}
  ],
  "ENROLLMENTS": [
