209			t.Fatalf("停开课程应仍可建立要求，code=%d out=%q", code, out)
210		}
211		// 新增修读受停开限制：业务拒绝退出码 1，而不是文件损坏 2。
212		if _, errText, code := runCLI(t, file, "enroll", "s2", "r2", "2024秋", "e2"); code != exitRejected {
213			t.Fatalf("停开课程新增修读应业务拒绝（退出码 %d），code=%d err=%q",
