220		}
221		// 并参与核对。
222		if out, _, code := runCLI(t, file, "check", "s1"); code != 0 ||
223			!strings.Contains(out, "总学分：4") {
224			t.Fatalf("停开课程的通过修读应照常计学分，code=%d out=%q", code, out)
225		}
226		// 上述写入（建要求、提交成绩）合法落盘后，文件仍能正常打开，且 c1 的
227		// 合法停开状态不被任何操作改写。
228		if out, _, code := runCLI(t, file, "list-courses"); code != 0 ||
