234	// TestCLINullTextInCourseNameAndBasisUnchanged 课程名称、免修依据中的普通
235	// 文字“null”是字符串值，不是开放状态空值，文件正常读取。
236	func TestCLINullTextInCourseNameAndBasisUnchanged(t *testing.T) {
237		d := &diskRecord{
238			Version: 1,
239			Courses: []diskCourse{
240				{ID: "c1", Name: "null", Credit: 4, Open: true},
241			},
242			Students: []diskStudent{{ID: "s1"}},
243			Waivers: []diskWaiver{
244				{ID: "w1", Student: "s1", Req: "rX", Basis: "依据里提到 null",
245					Status: "rejected", Reason: "目标要求 rX 不存在或不属于该学生"},
246			},
247		}
248		file, raw := writeDiskRecord(t, d)
249	
250		out, _, code := runCLI(t, file, "list-courses")
251		if code != 0 || !strings.Contains(out, "《null》") {
252			t.Fatalf("课程名称为文字 null 应正常显示，code=%d out=%q", code, out)
253		}
254		out, _, code = runCLI(t, file, "check", "s1")
255		if code != 0 || !strings.Contains(out, "被拒绝的免修") {
256			t.Fatalf("依据含文字 null 的被拒绝免修应正常列出，code=%d out=%q", code, out)
257		}
258		assertFileByteIdentical(t, file, raw, "只读访问之后：")
259	}
260	
261	// TestCLIOmittedOpenAndEmptyListsKeepLegacyRead 省略 open 字段的既有读取
262	// 规则与空数组/null 列表按空记录读取的规则都不在本次纠正范围内，保持不变。
263	func TestCLIOmittedOpenAndEmptyListsKeepLegacyRead(t *testing.T) {
264		// 省略 open：既有读取规则按零值（停开）处理，文件能打开、列表能显示。
265		omitted := `{"version":1,"courses":[{"id":"c1","name":"数学","credit":4}]}` + "\n"
266		file1 := filepath.Join(t.TempDir(), "records.json")
267		if err := os.WriteFile(file1, []byte(omitted), 0o600); err != nil {
268			t.Fatal(err)
269		}
270		out, _, code := runCLI(t, file1, "list-courses")
271		if code != 0 || !strings.Contains(out, "状态：停开") {
272			t.Fatalf("省略 open 应按既有规则读成停开并正常显示，code=%d out=%q", code, out)
273		}
274	
275		// 空数组与 null 列表：空记录正常使用。
276		for _, content := range []string{
277			`{"version":1,"courses":null,"students":[],"requirements":null,` +
278				`"enrollments":[],"waivers":null}` + "\n",
279			`{"version":1}` + "\n",
280		} {
281			file2 := filepath.Join(t.TempDir(), "records.json")
282			if err := os.WriteFile(file2, []byte(content), 0o600); err != nil {
283				t.Fatal(err)
284			}
285			if out, _, code := runCLI(t, file2, "list-courses"); code != 0 ||
286				!strings.Contains(out, "（尚无课程）") {
287				t.Fatalf("空数组/null 列表应按空记录读取，content=%q code=%d out=%q",
288					content, code, out)
289			}
290		}
291	}
